-- ── 5. History: one 'imported' event per new unit ──────────
INSERT INTO public.equipment_events (unit_id, kind, detail)
SELECT u.id, 'imported',
       CASE WHEN u.source->>'origin' = 'sortly'
            THEN 'Imported from the first Sortly inventory (Value tab, row ' || (u.source->>'sortly_row') || '). Not yet physically verified.'
            ELSE 'Imported from FFSA INVENTORY, tab ' || (u.source->>'tab') || ', row ' || (u.source->>'row') END
FROM public.equipment_units u
WHERE u.tag = ANY (ARRAY[
  'STU0001', 'STU0002', 'STU0003', 'STU0004', 'STU0005', 'STU0006', 'UCL0001', 'UCL0002',
  'UCL0003', 'UCL0004', 'UCL0005', 'UCL0006', 'UCL0007', 'UCL0008', 'UCL0009', 'UCL0010',
  'UCL0011', 'UCL0012', 'UCL0013', 'UCL0014', 'UCL0015', 'SBS-0001', 'SBS-0002', 'SBS-0003',
  'SBS-0004', 'SBS-0005', 'SBS-0006', 'SBS-0007', 'SBS-0008', 'SBS-0009', 'SBS-0010', 'DBS-0001',
  'DBS-0002', 'SRT-0017-01', 'SRT-0024-01', 'SRT-0020-01', 'SRT-0014-01', 'SRT-0014-02', 'SRT-0018-01', 'SRT-0016-01',
  'SRT-0016-02', 'SRT-0011-01', 'SRT-0011-02', 'SRT-0011-03', 'SRT-0011-04', 'SRT-0011-05', 'SRT-0011-06', 'SRT-0011-07',
